texto:
{
  "hechos": [
    {
      "id": "H1",
      "texto": "El acueducto de San Aurelio suspendió el suministro de agua potable en todo el casco urbano.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P4"]
    },
    {
      "id": "H2",
      "texto": "Alrededor de 18.000 suscriptores se ven afectados por el corte.",
      "tipo": "dato",
      "paginas": ["P1", "P3", "P4"]
    },
    {
      "id": "H3",
      "texto": "En la planta El Retiro se encontraron niveles de mercurio por encima del límite permitido.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H4",
      "texto": "El motivo sería la presencia de mercurio, por encima de lo que permite la norma.",
      "tipo": "dato",
      "paginas": ["P2"]
    },
    {
      "id": "H5",
      "texto": "Fabio Bermúdez contó a El Mirador que varias familias están recogiendo agua lluvia en baldes.",
      "tipo": "atribucion",
      "paginas": ["P2"]
    },
    {
      "id": "H6",
      "texto": "Ramiro Bermúdez contó a Voz del Valle que el olor del agua había cambiado desde hacía una semana.",
      "tipo": "atribucion",
      "paginas": ["P3"]
    },
    {
      "id": "H7",
      "texto": "Carolina Ospina contó a Diario Sabana que el agua embotellada se agotó en las tiendas del sector.",
      "tipo": "atribucion",
      "paginas": ["P4"]
    },
    {
      "id": "H8",
      "texto": "En el barrio San José, la junta de acción comunal contó 350 hogares sin agua.",
      "tipo": "dato",
      "paginas": ["P2"]
    },
    {
      "id": "H9",
      "texto": "En el barrio Los Almendros, la junta de acción comunal contó 110 hogares sin agua.",
      "tipo": "dato",
      "paginas": ["P2"]
    },
    {
      "id": "H10",
      "texto": "En el barrio Las Brisas, la junta de acción comunal contó 425 hogares sin agua.",
      "tipo": "dato",
      "paginas": ["P3"]
    },
    {
      "id": "H11",
      "texto": "En el barrio Villa Nueva, la junta de acción comunal contó 121 hogares sin agua.",
      "tipo": "dato",
      "paginas": ["P4"]
    }
  ]
}
